/**
 * The rules a world is generated by: what stood scattered through the generator as constants, and what
 * differs between one version of the generator and the next.
 *
 * A world of version 1 is every world made before there were versions, and it stays the same to the bit
 * (harness/sim/world_golden.test.ts is the judge): RULES_V1 is frozen in meaning as well as in value.
 * RULES_V2 is the generator being built in docs/V3/nodes/W1-worldgen.md. The two are separate objects, so
 * that the second can change without the first noticing.
 *
 * The road itself reads this file (spine.ts), so it stands below every other module of the world:
 * whatever it needs at run time — a quiet rule — may know the road, the landforms, the water and the
 * rest by their types only, never import them to run (the modules would load in a circle). A rule is
 * handed the chapter plan when it is asked, and the plan holds the rules: `plan.rules.slot` is the
 * length of a stretch, `plan.rules.regionCount` how many regions the world knows.
 */
import { BIOMES, FIRST_BIOMES, MIN_RADIUS_ANY } from './biomes';
import { quietSlot } from './quiet';
import type { ChapterPlan } from './spine';

/** the versions of the generator there are */
export type WorldVersion = 1 | 2;

/**
 * Is stretch k of the road one of the journey's quiet ones (no place to stop, no lake, no bridge, no
 * colossal remain)? Decided from dice and the chapter plan alone, so that the water, the places and the
 * landmarks all agree, whoever asks first.
 */
export type QuietRule = (plan: ChapterPlan, seed: number, k: number) => boolean;

/** what keeps the road a road: x always increasing along it, no curve the meshes cannot follow, no grade a loaded car cannot climb */
export interface RoadRules {
  /**
   * Heading guards, in degrees either side of +x: from 0 to `headingSoft` a new curve is ever more
   * likely to turn back towards +x; no curve is planned to carry the heading beyond `headingLimit`, and
   * one with less than `headingRoom` of room left on its side turns the other way; a curve that would
   * still unwind beyond `headingHard` is met with a counter-curve.
   */
  readonly headingSoft: number;
  readonly headingLimit: number;
  readonly headingRoom: number;
  readonly headingHard: number;
  /** no curve is tighter than this, whatever a region's design speed says (m) */
  readonly radiusFloor: number;
  /** no grade is steeper than this, whatever a region's own limit says (rise per metre) */
  readonly gradeCap: number;
}

export interface WorldRules {
  readonly version: WorldVersion;
  /**
   * How many entries of the region registry (biomes.ts BIOMES) this world knows. Regions are only ever
   * appended to the registry, so a world keeps its count and never sees the ones that came after it.
   */
  readonly regionCount: number;
  /**
   * Metres of road per stretch: landforms, water, places and quiet stretches are all laid out on this
   * one grid (the plans' own constants LAND_SLOT, WATER_SLOT and SITE_SLOT must equal it: terrain.ts
   * checks when a world is made).
   */
  readonly slot: number;
  /** the length over which two regions blend into each other at a chapter border (m), by chapter scale */
  readonly transition: (scale: number) => number;
  /** which stretches are left quiet */
  readonly quiet: QuietRule;
  readonly road: RoadRules;
}

/** the kinds of country version 1 deals from once a journey is under way: the six there were when it was written */
const V1_REGIONS = 6;

const ROAD_V1: RoadRules = Object.freeze({ headingSoft: 40, headingLimit: 44, headingRoom: 8, headingHard: 49, radiusFloor: MIN_RADIUS_ANY, gradeCap: 0.08 });

/** Version 1: every world made before there were versions. Nothing here may change. */
export const RULES_V1: WorldRules = Object.freeze({
  version: 1,
  regionCount: V1_REGIONS,
  slot: 1250,
  transition: (scale: number): number => Math.max(300, 900 * Math.min(1, scale * 2)),
  // two neighbouring stretches in every block of nine, from the fourth chapter on (quiet.ts)
  quiet: quietSlot,
  road: ROAD_V1,
});

/**
 * Version 2 (docs/V3/nodes/W1-worldgen.md). It starts as version 1's values and functions; the tables
 * are written out again rather than shared, so that changing one here never reaches a version 1 world.
 * Its region count is the whole registry at the time a world is made (`rulesFor`); the number here is
 * only what it was when this file was loaded.
 */
export const RULES_V2: WorldRules = Object.freeze({
  version: 2,
  regionCount: BIOMES.length,
  slot: 1250,
  transition: (scale: number): number => Math.max(300, 900 * Math.min(1, scale * 2)),
  // ---- THE VERSION 2 QUIET RULE PLUGS IN HERE (src/core/world/director.ts: one quiet run to a region,
  // not at its ends); until it does, version 2 keeps version 1's blocks of nine
  quiet: quietSlot,
  road: Object.freeze({ headingSoft: 40, headingLimit: 44, headingRoom: 8, headingHard: 49, radiusFloor: MIN_RADIUS_ANY, gradeCap: 0.08 }),
});

/**
 * The rules of a world: its version's, with its own region count. Without a count a world of version 1
 * knows the six regions there were when version 1 was closed, and a world of version 2 every region
 * registered when it is made — which is why a save must keep the count (WorldOptions.regionCount).
 */
export function rulesFor(version: WorldVersion = 1, opts: { regionCount?: number } = {}): WorldRules {
  if (version !== 1 && version !== 2) throw new RangeError(`world version ${String(version)}: there are versions 1 and 2`);
  const base = version === 2 ? RULES_V2 : RULES_V1;
  const count = opts.regionCount ?? (version === 2 ? BIOMES.length : V1_REGIONS);
  // (at least the three kinds every journey begins in; at most what the registry holds)
  if (!Number.isInteger(count) || count < FIRST_BIOMES || count > BIOMES.length) {
    throw new RangeError(`regionCount ${String(count)}: a world knows between ${FIRST_BIOMES} regions and all ${BIOMES.length} of the registry`);
  }
  return count === base.regionCount ? base : Object.freeze({ ...base, regionCount: count });
}
